"""Hippie Station Engineering's front, generated by the node graph (forge/proc), the fourth department through it.

    python tools/mapforge/blueprints/engineering_v1.py            # run the graph, one picture per node
    python tools/mapforge/mapforge.py build blueprints/engineering_v1.py
    MAPFORGE_SEED=3 python tools/mapforge/mapforge.py build blueprints/engineering_v1.py

The engine room, the SMES, the gravity generator and telecomms are cores and stay as they are. What the outline
fixes: the engine room's north wall with its two doors, the open way west along it to the SMES, the walkway down the
east side; the break room's public door off the aft hallway. The rest is three blocks the solver cuts per seed: the
workshop row (secure storage, the workshop, the control desk), the CE's office beside the cycled rad airlock, and the
break room with the security checkpoint looking over it.
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, ".."))
from forge.proc import geo as G  # noqa: E402
from forge.proc import shell, furnish, emit, solve  # noqa: E402
from assets import engineering as assets  # noqa: E402
from forge.proc.shell import X, Y, door, glass, keep  # noqa: E402

NAME = "engineering_v1"
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
BASE_MAP = os.path.join(ROOT, "_maps", "map_files", "HippieStation", "hippiestation.dmm")
BBOX = (99, 74, 124, 93)
ENG = "/area/engine/engineering"
AREAS = (ENG, "/area/crew_quarters/heads/chief", "/area/engine/break_room", "/area/security/checkpoint/engineering")

# ---------------------------------------------------------------- inputs: what the outline fixes
ROW74 = [(x, 74) for x in range(99, 125)]           # the engine room's north wall and the open ends of it
WEST = [(x, 74) for x in range(99, 106)]            # the way west to the SMES, open floor
ENGINE_DOORS = [(112, 74), (114, 74)]
WALKWAY = [(121, 74), (122, 74), (123, 74)]          # the east walkway down beside the engine
PUBLIC = (116, 86)                                   # the break room's door off the aft hallway
PUBLIC_GLASS = [(116, 85), (116, 87)]


def in_zone(a):
    return a in AREAS


PARAMS = dict(seed=1)

FLOOR, DARKF = "/turf/open/floor/plasteel", "/turf/open/floor/plasteel/dark"
APC_ENGINE = "/obj/machinery/power/apc/highcap/fifteen_k"
ROOM_TABLE = {
    "foyer": dict(area=ENG, floor=FLOOR, name="Engineering", hall=True, apc=APC_ENGINE, label="FOYER"),
    "storage": dict(area=ENG, floor=DARKF, name="Engineering Secure Storage", apc=APC_ENGINE, label="STORE"),
    "workshop": dict(area=ENG, floor=FLOOR, name="Engineering Workshop", apc=APC_ENGINE, label="SHOP"),
    "control": dict(area=ENG, floor=DARKF, name="Engineering Control", apc=APC_ENGINE, label="CTRL"),
    "airlock": dict(area=ENG, floor=FLOOR, name="Engineering Airlock", apc=APC_ENGINE, label="LOCK"),
    "ce": dict(area="/area/crew_quarters/heads/chief", floor=DARKF, name="Chief Engineer's Office",
               apc="/obj/machinery/power/apc/highcap/five_k", label="CE"),
    "break": dict(area="/area/engine/break_room", floor=FLOOR, name="Engineering Foyer", newscaster=True,
                  label="BREAK"),
    "checkpoint": dict(area="/area/security/checkpoint/engineering", floor=DARKF, name="Engineering Security Post",
                       label="SEC"),
}

WBLOCK = (100, 78, 113, 81)         # the workshop row, behind the foyer's north wall
SBLOCK = (115, 79, 123, 83)         # the CE and the rad airlock
NBLOCK = (117, 85, 123, 92)         # the break room and the checkpoint


def authored(P):
    return {
        "W": X((5, "storage"), (4, "workshop"), (1.0, "control")),
        "S": X((5, "ce"), (1.0, "airlock")),
        "N": Y((3, "checkpoint"), (1.0, "break")),
    }


def plans(P, fill=None):
    f = fill or authored(P)
    return [
        ((104, 75, 124, 75), "foyer"),
        ((100, 76, 124, 76), "foyer"),
        ((115, 77, 124, 77), "foyer"),              # the wide east end, where the tool racks stand
        (WBLOCK, f["W"]),
        (SBLOCK, f["S"]),
        (NBLOCK, f["N"]),
    ]


def program(P):
    """The three free blocks as a room list. The airlock must reach from the foyer to the break room; the break
    room must take the public door and meet the airlock; the CE on the foyer."""
    blocks = [
        solve.Block("W", WBLOCK, {"s": ("foyer", WBLOCK[0], WBLOCK[2])}),
        solve.Block("S", SBLOCK, {"s": ("foyer", SBLOCK[0], SBLOCK[2]), "n": ("north", 117, 123)}),
        solve.Block("N", NBLOCK, {"s": ("south", 117, 123), "w": ("public", 85, 87)}),
    ]
    W = solve.Want
    wants = [
        W("storage", 20, min=(4, 4), front=("foyer",)),
        W("workshop", 16, min=(4, 4), front=("foyer",)),
        W("control", 12, min=(3, 4), front=("foyer",)),
        W("ce", 25, min=(4, 4), front=("foyer",)),
        W("airlock", 15, min=(3, 3), front=("foyer", "north"), fixed={"w": 3}),
        W("break", 28, min=(4, 4), front=("public", "south"), anchors=[(117, 86)]),
        W("checkpoint", 15, min=(3, 3), front=(), near=("break",)),
    ]
    return blocks, wants


LINK_PAIRS = [("checkpoint", "break")]


def seeded(seed, tries=8):
    last = None
    for t in range(tries):
        P = dict(PARAMS)
        blocks, wants = program(P)
        trees, rects, report = solve.solve(blocks, wants, LINK_PAIRS, seed="%s.%d" % (seed, t), ratio=(0.5, 1.8),
                                           fill=True, fixed={"storage": "W", "workshop": "W", "control": "W",
                                                             "ce": "S", "airlock": "S",
                                                             "break": "N", "checkpoint": "N"})
        if trees is None:
            break
        g = graph(fill=trees)
        geo = g.run()
        geo.notes[:0] = report + ["seed %s: try %d, %d problems" % (seed, t, len(geo.problems))]
        last = (g, geo)
        if not geo.problems:
            break
    return last


ENGD = dict(kind="engineering", access="10")
CYCLE = "/obj/effect/mapping_helpers/airlock/cyclelink_helper"
LINKS = [
    keep(WEST[-2], "foyer"), keep(WEST[-1], "foyer"),
    keep(ENGINE_DOORS[0], "foyer"), keep(ENGINE_DOORS[1], "foyer"),
    keep(WALKWAY[0], "foyer"), keep(WALKWAY[1], "foyer"), keep(WALKWAY[2], "foyer"),
    keep(PUBLIC, "break"),
    # the rad airlock: cycled doors, the break room end under the lockdown blast door
    door("airlock", "foyer", name="Engineering", glass=True, extra=[(CYCLE, {"dir": 1})], **ENGD),
    door("airlock", "break", type="blast", id="Engineering", name="Engineering", kind="engineering", access="10",
         extra=[(CYCLE, {"dir": 2})]),
    # the workshop row
    door("storage", "foyer", type="blast", id="Secure Storage", name="Engineering Secure Storage", kind="engineering",
         access="11"),
    door("workshop", "foyer", name="Engineering Workshop", glass=True, **ENGD),
    door("control", "foyer", name="Engineering Control", glass=True, **ENGD), glass("control", "foyer"),
    # the chief: a glass door and privacy shutters onto the foyer
    door("ce", "foyer", name="Chief Engineer", kind="command", glass=True, access="56"),
    glass("ce", "foyer"),
    # the checkpoint looks over the break room
    door("checkpoint", "break", name="Security Post - Engineering", kind="security", glass=True, access="63"),
    glass("checkpoint", "break"),
]


SEED = int(os.environ.get("MAPFORGE_SEED", "1"))
if SEED != 1:
    PARAMS["seed"] = SEED
    NAME += "_s%d" % SEED


def graph(fill=None, **over):
    P = dict(PARAMS)
    P.update(over)
    g = G.Graph(NAME, **P)
    g.add("outline", shell.outline, view="kind", base=BASE_MAP, bbox=BBOX, in_zone=in_zone,
          keep=[p for p in ROW74 if p not in WEST + ENGINE_DOORS + WALKWAY] + PUBLIC_GLASS,
          gates=WEST + ENGINE_DOORS + WALKWAY + [PUBLIC])
    g.add("slice", shell.slice_rooms, view="rooms", plans=plans(P, fill), rooms=ROOM_TABLE)
    g.add("tidy", shell.tidy, view="rooms")
    g.add("openings", shell.openings, view="rooms", links=LINKS)
    g.add("fields", shell.fields, view="fields")
    g.add("furnish", furnish.furnish, view="items", assets=assets.ASSETS)
    return g


_graph, _geo = seeded(SEED) if SEED != 1 else (graph(), None)
_geo = _geo or _graph.run()
globals().update(emit.blueprint(_geo, NAME, extra=dict(STYLE="meta", DISPOSALS="route", DRESS_HALL_FRONT=True,
                                                       BASE=BASE_MAP)))


def main():
    g, geo = _graph, _geo
    out = os.path.join(ROOT, "data", "previews", "mapforge", "proc")
    paths = g.pictures(out, tile=20)
    G.sheet(paths, os.path.join(out, NAME + "_nodes.png"), cols=3)
    G.draw(geo, "items", os.path.join(out, NAME + "_furnish_big.png"), tile=30, title="furnish")
    for n in geo.notes:
        print(n)
    for p in geo.problems:
        print("PROBLEM", p)
    print("pictures:", os.path.relpath(os.path.join(out, NAME + "_nodes.png"), ROOT))


if __name__ == "__main__":
    main()
